def longest_non_increasing_prefix_length(arr):
    if not arr:
        return 0
    length = 1
    for i in range(1, len(arr)):
        if arr[i] <= arr[i - 1]:
            length += 1
        else:
            break
    return length

def rotate_string_left(s, n):
    if not s:
        return ""
    n = n % len(s)
    return s[n:] + s[:n]

def render_template(template, values):
    result = template
    for k, v in values.items():
        result = result.replace('{' + k + '}', str(v))
    return result

import math
def are_coprime(a, b):
    return math.gcd(a, b) == 1

def find_longest_common_suffix_length(a, b):
    n = min(len(a), len(b))
    i = 0
    while i < n and a[len(a) - 1 - i] == b[len(b) - 1 - i]:
        i += 1
    return i

def group_consecutive_same_case(s):
    letters = [c for c in s if c.isalpha()]
    if not letters:
        return []
    groups = []
    current = letters[0]
    for c in letters[1:]:
        if c.isupper() == current[-1].isupper():
            current += c
        else:
            groups.append(current)
            current = c
    groups.append(current)
    return groups

def time_zone_shift(time_str, hour_offset):
    h, m = time_str.split(':')
    total = int(h)*60 + int(m) + hour_offset*60
    day_offset = total // 1440
    rem = total % 1440
    return (day_offset, f'{rem//60:02d}:{rem%60:02d}')

def sort_by_bit_count(nums):
    def bits(n):
        return bin(abs(n)).count('1')
    return sorted(nums, key=lambda n: (bits(n), n))

def count_elements_less_than_median(nums):
    s = sorted(nums)
    n = len(s)
    med = float(s[n // 2]) if n % 2 == 1 else (s[n // 2 - 1] + s[n // 2]) / 2
    return sum(1 for x in nums if x < med)

def age_difference_in_years(birth1, birth2, today):
    def age(birth):
        by, bm, bd = birth
        ty, tm, td = today
        y = ty - by
        if (tm, td) < (bm, bd):
            y -= 1
        return y
    return age(birth1) - age(birth2)

def is_valid_grid_reference(s):
    if len(s) < 2:
        return False
    if not s[0].isalpha() or not s[0].isupper():
        return False
    digits = s[1:]
    if not digits.isdigit():
        return False
    if len(digits) > 1 and digits[0] == '0':
        return False
    return 1 <= int(digits) <= 99

def is_practical_number(n):
    if n == 1:
        return True
    divs = sorted(i for i in range(1, n + 1) if n % i == 0)
    if divs[0] != 1:
        return False
    total = 1
    for d in divs[1:]:
        if d > total + 1:
            return False
        total += d
    return True

def count_primes_in_range(a, b):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    return sum(1 for x in range(a, b + 1) if is_prime(x))

def compress_repeated_chars(s):
    if not s:
        return ""
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(prev + str(count))
            prev = c
            count = 1
    result.append(prev + str(count))
    return ''.join(result)

import math
def is_sum_of_two_squares(n):
    a = 0
    while a * a <= n:
        b2 = n - a * a
        b = math.isqrt(b2)
        if b * b == b2:
            return True
        a += 1
    return False

def add_business_days(start_day_num, n, weekend_days):
    d = start_day_num
    count = 0
    while count < n:
        d += 1
        if d % 7 not in weekend_days:
            count += 1
    return d

