    filtered = [c.lower() for c in s if c.isalnum()]
    return filtered == filtered[::-1]

def is_repunit(n):
    s = str(n)
    return all(c == '1' for c in s)

def bucket_sort_into_ranges(nums, boundaries):
    k = len(boundaries) - 1
    buckets = [[] for _ in range(k)]
    for v in nums:
        for i in range(k):
            lo, hi = boundaries[i], boundaries[i + 1]
            if (v >= lo and v < hi) or (i == k - 1 and v == hi):
                buckets[i].append(v)
                break
    return [sorted(b) for b in buckets]

def find_duplicates(lst):
    seen = set()
    added = set()
    result = []
    for x in lst:
        if x in seen and x not in added:
            result.append(x)
            added.add(x)
        seen.add(x)
    return result

def remove_adjacent_duplicate_pairs(lst):
    stack = []
    for x in lst:
        if stack and stack[-1] == x:
            stack.pop()
        else:
            stack.append(x)
    return stack

def is_valid_stopwatch_time(s):
    import re
    m = re.fullmatch(r'(\d+):(\d{2})', s)
    if not m:
        return False
    minutes, seconds = m.groups()
    if len(minutes) > 1 and minutes[0] == '0':
        return False
    return int(seconds) <= 59

def frequency_rank_map(items):
    c = {}
    first_idx = {}
    for i, x in enumerate(items):
        if x not in c:
            first_idx[x] = i
        c[x] = c.get(x, 0) + 1
    uniq = sorted(c.keys(), key=lambda x: (-c[x], first_idx[x]))
    return {x: i + 1 for i, x in enumerate(uniq)}

def is_valid_ipv4_cidr(s):
    if s.count('/') != 1:
        return False
    ip, prefix = s.split('/')
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        if int(p) > 255:
            return False
    if not prefix.isdigit():
        return False
    if len(prefix) > 1 and prefix[0] == '0':
        return False
    return 0 <= int(prefix) <= 32

def is_undulating_number(n):
    s = str(abs(n))
    if len(s) < 3:
        return False
    if s[0] == s[1]:
        return False
    for i in range(2, len(s)):
        if s[i] != s[i - 2]:
            return False
    return True

def wrap_with_indent(text, width, indent):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        limit = width if not lines else width - indent
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        out.append(line if i == 0 else " " * indent + line)
    return out

def wrap_in_quotes(s):
    escaped = s.replace('"', '\\"')
    return '"' + escaped + '"'

def is_palindrome_base(n, b):
    if n == 0:
        return True
    digits = []
    x = n
    while x > 0:
        digits.append(x % b)
        x //= b
    return digits == digits[::-1]
